package config

// AvatarIDs mirrors web/avatars/avatars.js (generated by
// tools/avatar-src/make_avatars.py). It exists so a new bot never looks like an
// existing one: the first id not in use is assigned automatically.
var AvatarIDs = []string{
	"maus", "clover", "ember", "luna", "pip", "nori",
	"mochi", "rocky", "zest", "cocoa", "frost", "raven",
}

// NextAvatar picks the first avatar id no current bot uses, falling back to a
// round-robin by bot count once every face is taken.
func (s *Settings) NextAvatar() string {
	used := map[string]bool{}
	for _, b := range s.Snapshot() {
		if b.Avatar != "" {
			used[b.Avatar] = true
		}
	}
	for _, id := range AvatarIDs {
		if !used[id] {
			return id
		}
	}
	return AvatarIDs[len(s.Snapshot())%len(AvatarIDs)]
}
